package mz.co.aprendaacodar.user.controller;
import jakarta.validation.Valid;import mz.co.aprendaacodar.user.dto.TeacherDtos.*;import mz.co.aprendaacodar.user.service.TeacherService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/admin/teachers") @PreAuthorize("hasRole('ADMIN')") public class TeacherController {private final TeacherService service;public TeacherController(TeacherService s){service=s;}
 @PostMapping public TeacherResponse create(@Valid @RequestBody CreateTeacherRequest r){return service.create(r);}@GetMapping public List<TeacherResponse> list(){return service.list();}@GetMapping("/{id}") public TeacherResponse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}") public TeacherResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateTeacherRequest r){return service.update(id,r);}@PatchMapping("/{id}/deactivate") public void deactivate(@PathVariable UUID id){service.deactivate(id);}}
